function range(a, b) {
  const out = [];
  for (let i = a; i <= b; i++) out.push(i);
  return out;
}
module.exports = { range };

js-add-slugify.strings.js:
function capitalize(s) { return s.charAt(0).toUpperCase() + s.slice(1); }
function slugify(text) {
  return String(text).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}
module.exports = { capitalize, slugify };

js-async-foreach.loader.js:
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function load(id) { await sleep(10 * (3 - id)); return { id }; }
async function fetchAll(ids) { return Promise.all(ids.map((id) => load(id))); }
module.exports = { fetchAll, load };

js-make-tests-pass.stack.js:
class Stack {
  constructor() { this.items = []; }
  get size() { return this.items.length; }
  push(x) { this.items.push(x); }
  peek() { return this.items[this.items.length - 1]; }
  pop() { if (!this.items.length) throw new Error('Stack is empty'); return this.items.pop(); }
}
module.exports = Stack;

